const SHEET_ID = "YOUR_GOOGLE_SHEET_ID";
const TELEGRAM_CHAT_ID = "YOUR_TELEGRAM_CHAT_ID";
const TOTAL_MILESTONE      = 5;
const MAKS_PANJANG_JAWABAN = 900;
return [{ json: { SHEET_ID, TELEGRAM_CHAT_ID, TOTAL_MILESTONE, MAKS_PANJANG_JAWABAN } }];

function normalisasiNomor(nilai) {
  let d = String(nilai || "").replace(/[^0-9]/g, "");
  if (d.length === 0) return "";
  if (d.indexOf("0") === 0) d = "62" + d.slice(1);
  if (d.indexOf("62") !== 0 && d.length >= 9 && d.length <= 11) d = "62" + d;
  return d;
}

const hasil = { valid: false, alasan: "", no_wa: "", nama_pengirim: "", pesan: "", sumber: "", id_pesan: "" };

let body = {};
try {
  const waItem = $("WhatsApp Trigger").first().json;
  if (waItem && typeof waItem === "object") { body = waItem; }
} catch(e) {}

// Hanya fallback ke Webhook kalau WA Trigger tidak punya data yang dikenali
if (!body.object && !body.from && !body.message && !body.no_wa && !body.nomor && !body.messaging_product) {
  try { body = $("Webhook Pesan Masuk").first().json.body || {}; } catch(e) {}
}

// --- Bentuk 1: Meta raw payload (object + entry) ---
if (body.object === "whatsapp_business_account" && Array.isArray(body.entry)) {
  const value = body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]
    ? body.entry[0].changes[0].value : null;
  if (!value) {
    hasil.alasan = "payload WhatsApp tanpa changes";
  } else if (Array.isArray(value.statuses) && !Array.isArray(value.messages)) {
    hasil.alasan = "callback status pengiriman, bukan pesan pelanggan";
  } else {
    const m = Array.isArray(value.messages) ? value.messages[0] : null;
    if (!m) {
      hasil.alasan = "tidak ada pesan di payload";
    } else if (m.type !== "text") {
      hasil.alasan = "tipe pesan " + m.type + " belum didukung";
    } else {
      const kontak = Array.isArray(value.contacts) ? value.contacts[0] : null;
      hasil.valid = true; hasil.sumber = "whatsapp";
      hasil.no_wa = normalisasiNomor(m.from);
      hasil.nama_pengirim = kontak && kontak.profile ? String(kontak.profile.name || "") : "";
      hasil.pesan = String(m.text.body || "").trim();
      hasil.id_pesan = String(m.id || "");
    }
  }
}
// --- Bentuk 2: n8n WhatsApp Trigger native (value level, messaging_product di root) ---
else if (body.messaging_product === "whatsapp" && Array.isArray(body.messages)) {
  const m = body.messages[0];
  if (!m) {
    hasil.alasan = "tidak ada pesan di payload WhatsApp Trigger";
  } else if (m.type !== "text") {
    hasil.alasan = "tipe pesan " + m.type + " belum didukung";
  } else {
    const kontak = Array.isArray(body.contacts) ? body.contacts[0] : null;
    hasil.valid = true; hasil.sumber = "whatsapp";
    hasil.no_wa = normalisasiNomor(m.from);
    hasil.nama_pengirim = kontak && kontak.profile ? String(kontak.profile.name || "") : "";
    hasil.pesan = String(m.text.body || "").trim();
    hasil.id_pesan = String(m.id || "");
  }
}
// --- Bentuk 3: n8n WhatsApp Trigger status update (buang) ---
else if (body.messaging_product === "whatsapp" && !Array.isArray(body.messages)) {
  hasil.alasan = "callback status pengiriman WhatsApp Trigger, bukan pesan pelanggan";
}
// --- Bentuk 4: n8n WhatsApp Trigger parsed per-message (from di root) ---
else if (body.from && (body.text || body.type)) {
  if (!body.text || !body.text.body) {
    hasil.alasan = "tipe pesan native WhatsApp Trigger tidak didukung";
  } else {
    hasil.valid = true; hasil.sumber = "whatsapp";
    hasil.no_wa = normalisasiNomor(body.from);
    hasil.nama_pengirim = String(body.name || body.from || "");
    hasil.pesan = String(body.text.body).trim();
    hasil.id_pesan = String(body.id || "");
  }
}
// --- Bentuk 5: update Telegram ---
else if (body.message && body.message.chat) {
  if (!body.message.text) {
    hasil.alasan = "pesan Telegram tanpa teks";
  } else {
    hasil.valid = true; hasil.sumber = "telegram";
    hasil.no_wa = normalisasiNomor(body.message.contact ? body.message.contact.phone_number : "");
    hasil.nama_pengirim = body.message.from ? String(body.message.from.first_name || "") : "";
    hasil.pesan = String(body.message.text).trim();
    hasil.id_pesan = String(body.message.message_id || "");
  }
}
// --- Bentuk 6: payload uji sederhana {no_wa, pesan} ---
else if ((body.no_wa || body.nomor) && (body.pesan || body.text)) {
  hasil.valid = true; hasil.sumber = "uji";
  hasil.no_wa = normalisasiNomor(body.no_wa || body.nomor);
  hasil.nama_pengirim = String(body.nama || "");
  hasil.pesan = String(body.pesan || body.text).trim();
  hasil.id_pesan = "uji-" + Date.now();
}
else {
  hasil.alasan = "bentuk payload tidak dikenali";
}

if (!hasil.valid || hasil.pesan.length === 0) {
  console.log("Payload diabaikan: " + (hasil.alasan || "pesan kosong"));
  return [];
}

return [{ json: hasil }];

const ATURAN_AGEN = [
  "Kamu adalah asisten onboarding WarungOS, aplikasi kasir (POS) dan inventori untuk warung serta restoran kecil di Indonesia. Kamu membalas pelanggan lewat WhatsApp.",
  "",
  "ATURAN KERAS:",
  "1. Bahasa Indonesia, ramah dan santai tapi sopan. Sapa dengan Kak. Maksimal 5 kalimat.",
  "2. Fakta produk HANYA boleh berasal dari tool cari_panduan. Kalau tidak kamu temukan di sana, katakan terus terang bahwa kamu belum menemukan jawabannya dan tawarkan bantuan tim. JANGAN mengarang fitur, harga, promo, batas transaksi, atau janji waktu.",
  "3. Untuk pertanyaan soal progres onboarding pelanggan ini, pakai tool cek_progress. Jangan menebak.",
  "4. Setiap kali selesai menjawab, WAJIB panggil tool catat_interaksi satu kali.",
  "5. Panggil tool escalate_to_human HANYA untuk: transaksi tercatat ganda, laporan penjualan tidak sesuai transaksi asli, dana settlement telat lebih dari 2 hari kerja, akun tidak bisa diakses dan reset password gagal, aktivitas mencurigakan, pelanggan marah atau minta bicara dengan manusia, atau urusan kontrak dan tagihan langganan. Di luar itu, jawab sendiri.",
  "6. Jangan menyalahkan pelanggan. Jangan menggurui.",
  "7. Keluarkan HANYA teks balasannya. Tanpa tanda kutip pembungkus, tanpa judul, tanpa menyebut nama tool yang kamu pakai, dan tanpa mengumumkan tindakan yang akan kamu lakukan seperti saya akan catat interaksi ini atau saya akan laporkan.",
  "",
  "Kalau pelanggan bertanya hal di luar WarungOS, arahkan kembali dengan sopan.",
  ""
].join("\n");
const cfg = $("Konfigurasi").first().json;
const masuk = $("Normalisasi Pesan Masuk").first().json;
function ekorNomor(nilai) {
  let d = String(nilai || "").replace(/[^0-9]/g, "");
  if (d.indexOf("0") === 0) d = "62" + d.slice(1);
  return d.slice(-9);
}
const ekorPengirim = ekorNomor(masuk.no_wa);
const semuaPelanggan = $("Ambil Pelanggan").all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && String(r.customer_id || "").indexOf("CUST-") === 0; });
let pelanggan = null;
if (ekorPengirim.length === 9) {
  pelanggan = semuaPelanggan.find(function (r) { return ekorNomor(r.no_wa) === ekorPengirim; }) || null;
}
if (!pelanggan) {
  return [{ json: {
    dikenal: false, no_wa: masuk.no_wa,
    nama_pengirim: masuk.nama_pengirim, pesan: masuk.pesan, sumber: masuk.sumber
  } }];
}
const id = String(pelanggan.customer_id).trim();
const ms = $("Ambil Progress").all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && String(r.customer_id || "").trim() === id; })
  .sort(function (a, b) { return Number(a.milestone_id) - Number(b.milestone_id); });
const selesai = ms.filter(function (m) { return String(m.status).trim().toLowerCase() === "selesai"; });
const belum = ms.filter(function (m) { return String(m.status).trim().toLowerCase() !== "selesai"; });
const tahapMacet = belum.length > 0 ? Number(belum[0].milestone_id) : 0;
const namaTahap = belum.length > 0 ? String(belum[0].nama_milestone || "") : "";
const catatanTahap = belum.length > 0 ? String(belum[0].catatan || "") : "";
let hariMacet = 0;
for (const m of belum) { const h = Number(m.hari_di_tahap_ini) || 0; if (h > hariMacet) hariMacet = h; }
const daftarMilestone = ms.map(function (m) {
  return "  " + m.milestone_id + ". " + m.nama_milestone + " - " + (String(m.status).trim().toLowerCase() === "selesai" ? "SELESAI" : "BELUM");
}).join("\n");
const konteks = [
  "=== DATA PELANGGAN YANG SEDANG BERTANYA ===",
  "Nama outlet: " + pelanggan.nama_bisnis, "ID pelanggan: " + id,
  "Kota: " + (pelanggan.kota || "-"), "Paket langganan: " + pelanggan.paket,
  "Status onboarding: " + pelanggan.status_onboarding, "",
  "Progres milestone (" + selesai.length + " dari " + cfg.TOTAL_MILESTONE + " selesai):",
  daftarMilestone, "",
  (belum.length > 0
    ? "Tahap yang sedang dikerjakan: milestone " + tahapMacet + " - " + namaTahap +
      " (sudah " + hariMacet + " hari di tahap ini). Catatan sistem: " + (catatanTahap || "tidak ada")
    : "Seluruh milestone sudah selesai."),
  "=== AKHIR DATA PELANGGAN ==="
].join("\n");
const tglSekarang = new Date().toISOString().slice(0, 10);
return [{ json: {
  dikenal: true, customer_id: id, nama_bisnis: pelanggan.nama_bisnis,
  no_wa: String(pelanggan.no_wa || ""), paket: pelanggan.paket,
  status_onboarding: pelanggan.status_onboarding, tahap_macet: tahapMacet,
  nama_tahap_macet: namaTahap, hari_macet: hariMacet,
  jumlah_milestone_selesai: selesai.length, pesan: masuk.pesan,
  sumber: masuk.sumber, nama_pengirim: masuk.nama_pengirim,
  konteks_pelanggan: konteks, system_message: ATURAN_AGEN + "\n" + konteks,
  log_id_b: "LOG-" + tglSekarang.replace(/-/g, "") + "-" + id.replace("CUST-", "") + "-B",
  log_tanggal: tglSekarang
} }];

const cfg = $("Konfigurasi").first().json;
const asal = $("Cocokkan Pelanggan").first().json;
let teks = String($json.output || $json.text || "").trim();
teks = teks.replace(/^[\s"'`]+/, "").replace(/[\s"'`]+$/, "").trim();
const masalah = [];
if (teks.length === 0) masalah.push("keluaran agen kosong");
if (teks.length > cfg.MAKS_PANJANG_JAWABAN) masalah.push("terlalu panjang (" + teks.length + " karakter)");
if (/\b(gratis|diskon|promo|refund|dijamin)\b/i.test(teks)) masalah.push("mengandung janji komersial");
let sumber = "ai";
